231	/*
232	 * Composite text-style classes — the full typographic intent of a role in one
233	 * class, including font-variation-settings, which has no Tailwind utility.
234	 *
235	 * Deliberately in `components`, NOT `utilities`: BaseText applies these as role
236	 * DEFAULTS, the ambient layer under everything else. Typography changes go
237	 * through BaseText props, which are written inline and so outrank the role
238	 * class; typography utilities are not a supported override, in DS code or in a
239	 * consuming app.
240	 *
241	 * Nothing here sets line-height: leading is left to inherit, and the consuming
242	 * app sets it per instance with the lineHeight prop.
243	 */
244	@layer components {
245	  /* .ds-chat-prose (dooph-component-tokens.css) re-spells four of these roles
246	   * by hand: title (h1), heading (h2), subheading (h3), mono (code). A
247	   * property added to one of those roles must be added there too. */
248	  .text-style-button {
249	    font-family: var(--ui-font-button);
250	    font-optical-sizing: auto;
251	    font-size: var(--ui-text-body);
252	    font-style: normal;
253	    font-weight: var(--ui-weight-button);
254	    font-variation-settings: var(--ui-font-var-button);
255	  }
256	
257	  .text-style-body {
258	    font-family: var(--ui-font-body);
259	    font-optical-sizing: auto;
260	    font-size: var(--ui-text-body);
261	    font-style: normal;
262	    font-weight: var(--ui-weight-body);
263	    font-variation-settings: var(--ui-font-var-body);
264	    letter-spacing: var(--ui-tracking-body);
265	  }
266	
267	  /* The hero-scale pair. Each is byte-identical to its base role apart from the
268	   * size token — same family, weight, axes and tracking — so they read as the
269	   * same voice set larger, not as a second one. Keep them in sync by hand if a
270	   * base role gains a property; they are spelled out rather than composed
271	   * because BaseText applies exactly one role class per element, so each must
272	   * stand alone. */
273	  .text-style-hero-body {
274	    font-family: var(--ui-font-body);
275	    font-optical-sizing: auto;
276	    font-size: var(--ui-text-hero-body);
277	    font-style: normal;
278	    font-weight: var(--ui-weight-body);
279	    font-variation-settings: var(--ui-font-var-body);
280	    letter-spacing: var(--ui-tracking-body);
281	  }
282	
283	  .text-style-hero-button {
284	    font-family: var(--ui-font-button);
285	    font-optical-sizing: auto;
286	    font-size: var(--ui-text-hero-button);
287	    font-style: normal;
288	    font-weight: var(--ui-weight-button);
289	    font-variation-settings: var(--ui-font-var-button);
290	  }
291	
292	  /* Mono deliberately mirrors button's size and weight (both tokens alias it)
293	   * so a mono run set beside a button label sits at the same optical scale.
294	   * The MONO axis is named explicitly — see the token's note on why trusting
295	   * the family default is not enough. */
296	  .text-style-mono {
297	    font-family: var(--ui-font-mono);
298	    font-optical-sizing: auto;
299	    font-size: var(--ui-text-mono);
300	    font-style: normal;
301	    font-weight: var(--ui-weight-mono);
302	    font-variation-settings: var(--ui-font-var-mono);
303	    letter-spacing: var(--ui-tracking-mono);
304	  }
305	
306	  .text-style-label {
307	    font-family: var(--ui-font-label);
308	    font-size: var(--ui-text-label);
309	    font-weight: var(--ui-weight-label);
310	    letter-spacing: var(--ui-tracking-label);
311	  }
