889	   *   --ds-spinner-gap          visual-gap allowance between the arcs,
890	   *                             as a fraction of one turn
891	   *   --ds-spinner-sweep-min/-max  the arc's length range, fractions of a turn
892	   *   --ds-spinner-time-scale   per-size factor on the spin duration
893	   *
894	   * Flat: Material's circular indeterminate recipe. The group turns at a
895	   * constant rate, one turn per --ui-spinner-rotate-duration. On the <svg>,
896	   * --ds-spinner-grow and --ds-spinner-tail (ds-spinner-dash keyframes, on
897	   * the standard curve per segment) move the arc along its path: first the
898	   * head races ahead while the tail creeps (the arc grows to its max sweep),
899	   * then the tail chases the head, which is held at the end of the first lap
900	   * (sweep is clipped to 1 − tail), so the arc shrinks to a dot and the cycle
901	   * restarts from it. Turn and dash run as two independent loops, as in
902	   * Material.
903	   *
904	   * The path is a TWO-lap open circle starting one gap before 12 o'clock, so
905	   * path position p (in turns along the path) sits p − gap turns past
906	   * 12 o'clock. The arc covers [gap + tail, gap + tail + sweep] and the track, its
907	   * complement a gap clear of each end, [tail + sweep + 2·gap, tail + 1]:
908	   * both stay strictly inside (0, 2) turns, so neither dash ever reaches
909	   * either end of the path (a dash cut by the path's seam splits in two and
910	   * its round caps flash). Each dash pattern's gap is the whole path (2C),
911	   * so no second dash ever appears. Both dashes are positioned in user units
912	   * (× 1px, which is one user unit inside an SVG).
913	   *
914	   * Reduced motion: loops are off the scale, so the global block cannot
915	   * reach them. The flat arc freezes at its longest, tail at 12 o'clock;
916	   * the spokes and star stop turning. */
917	  .ds-spinner-flat {
918	    animation: ds-spinner-dash var(--ui-spinner-duration)
919	      var(--ui-motion-ease-standard) infinite;
920	  }
921	  .ds-spinner-flat-turn {
922	    transform-box: view-box;
923	    transform-origin: 50% 50%;
924	    animation: ds-spinner-rotate var(--ui-spinner-rotate-duration)
925	      var(--ui-motion-ease-linear) infinite;
926	  }
927	  .ds-spinner-flat-arc {
928	    --ds-spinner-sweep: min(
929	      calc(
930	        var(--ds-spinner-sweep-min) +
931	          (var(--ds-spinner-sweep-max) - var(--ds-spinner-sweep-min)) *
932	          var(--ds-spinner-grow)
933	      ),
934	      calc(1 - var(--ds-spinner-tail))
935	    );
936	  }
937	  /* Active arc: starts `tail` past 12 o'clock and runs `sweep` of a turn. */
938	  .ds-spinner-flat-indicator {
939	    stroke-dasharray:
940	      calc(var(--ds-spinner-sweep) * var(--ds-spinner-c) * 1px)
941	      calc(var(--ds-spinner-c) * 2px);
942	    stroke-dashoffset: calc(
943	      (var(--ds-spinner-gap) + var(--ds-spinner-tail)) *
944	        var(--ds-spinner-c) * -1px
945	    );
946	  }
947	  /* Track: the complement, a gap clear of the arc at both ends. */
948	  .ds-spinner-flat-track {
949	    stroke-dasharray:
950	      max(
951	        0px,
952	        calc(
953	          (1 - var(--ds-spinner-sweep) - 2 * var(--ds-spinner-gap)) *
954	            var(--ds-spinner-c) * 1px
955	        )
956	      )
957	      calc(var(--ds-spinner-c) * 2px);
958	    stroke-dashoffset: calc(
959	      (
960	          var(--ds-spinner-tail) + var(--ds-spinner-sweep) + 2 *
961	            var(--ds-spinner-gap)
962	        ) *
963	        var(--ds-spinner-c) * -1px
964	    );
965	  }
966	  /* Spokes and star: a constant linear turn of an inner group. */
967	  .ds-spinner-spin {
968	    transform-box: view-box;
969	    transform-origin: 50% 50%;
970	    animation: ds-spinner-rotate
971	      calc(var(--ui-spinner-spokes-duration) * var(--ds-spinner-time-scale, 1))
972	      var(--ui-motion-ease-linear) infinite;
973	  }
974	  @media (prefers-reduced-motion: reduce) {
975	    .ds-spinner-flat {
976	      animation: none;
977	      --ds-spinner-grow: 1;
978	      --ds-spinner-tail: 0;
979	    }
980	    .ds-spinner-flat-turn,
981	    .ds-spinner-spin {
982	      animation: none;
983	    }
