986	  /* DropdownCaret. State is read from the nearest .ds-dropdown-caret-host
987	   * (the trigger root): Radix data-state, :hover, and the disabled forms.
988	   * The shape is painted by currentColor, so every state is a colour here. */
989	  .ds-dropdown-caret {
990	    --ds-dropdown-caret-frame: calc(var(--ui-height-button) - var(--ui-spacing-md));
991	    /* Closed: the primary button's background. */
992	    color: var(--ui-color-primary);
993	    transition: color var(--ui-motion-duration-base) var(--ui-motion-ease-enter);
994	  }
995	  .ds-dropdown-caret-chevron {
996	    transition:
997	      rotate var(--ui-shape-morph-duration) var(--ui-shape-morph-ease),
998	      color var(--ui-motion-duration-base) var(--ui-motion-ease-enter);
999	  }
1000	  /* Expressive detail: the caret's SHAPE, read from --ui-caret-shape-scale
1001	   * (an expression token; the practical preset sets it to 0). Every read of it
1002	   * lives in a .ds-expr-caret-shape rule.
1003	   *   1  the signature caret: a square the trigger's height, the morphing
1004	   *      shape in a frame of height-button minus spacing-md, and the chevron in
1005	   *      the primary FOREGROUND, because it sits on the shape.
1006	   *   0  a plain chevron: no frame (the shape fills the frame, so it draws
1007	   *      nothing), the root shrinks to the chevron plus a trailing inset that
1008	   *      mirrors the host's leading pl-md (+1px for the -mr-px pull over
1009	   *      the border), and the chevron takes the trigger's text colour.
1010	   * Values in between interpolate; 0 and 1 are the designed settings. The
1011	   * frame may be narrower than the chevron: it overflows centred, and the
1012	   * root's own width is what lays out. */
