1014	    width: calc(
1015	      var(--ui-height-button) * var(--ui-caret-shape-scale) +
1016	        (var(--ui-icon-rg) + var(--ui-spacing-md) + 1px) *
1017	        (1 - var(--ui-caret-shape-scale))
1018	    );
