1117	    width: var(--ds-reveal-change-width, auto);
1118	    transition-duration: var(--ui-motion-duration-slower);
1119	  }
1120	  .ds-reveal-change-content {
1121	    display: inline-flex;
1122	    flex-shrink: 0;
1123	    align-items: center;
1124	    white-space: nowrap;
1125	  }
