1	// No "use client": useId is exported by React's server build, so this module is
2	// neutral — it renders in either graph.
3	import { forwardRef, useId, type ComponentPropsWithoutRef } from "react";
4	import { cn } from "../../utils/cn";
5	import { WavyDividerVariant } from "./constants";
6	
7	
8	// ── Wave geometry (px) ───────────────────────────────────────────────────────
9	// Mirrors the Figma "Wavy Divider" node: one crest + one trough per period with
10	// a deliberately shallow, fixed amplitude. The wave lives in a 12px band so the
11	// stroke stays inside the host container (default 2px → strokes up to ~6px never
12	// clip), and the pattern repeats horizontally to fill any width — no JS measuring.
13	
14	const TILE_WIDTH: Record<WavyDividerVariant, number> = { high: 20, low: 40 };
15	const HEIGHT = 12;
16	const CENTER_Y = HEIGHT / 2;
17	const AMPLITUDE = 2.88;
18	// Symmetric cubic control points overshoot by 4/3 so the curve's midpoint peak
19	// lands exactly at AMPLITUDE.
20	const CONTROL_DELTA = AMPLITUDE * (4 / 3);
21	
22	/** One full period: a trough then a crest, vertically centered. */
23	function wavePath(tileWidth: number) {
24	  const half = tileWidth / 2;
25	  const trough = CENTER_Y + CONTROL_DELTA;
26	  const crest = CENTER_Y - CONTROL_DELTA;
27	  return [
28	    `M 0 ${CENTER_Y}`,
29	    `C ${half / 3} ${trough} ${(half * 2) / 3} ${trough} ${half} ${CENTER_Y}`,
30	    `C ${half + half / 3} ${crest} ${half + (half * 2) / 3} ${crest} ${tileWidth} ${CENTER_Y}`,
31	  ].join(" ");
32	}
33	
34	// ── Types ─────────────────────────────────────────────────────────────────────
35	
36	export type WavyDividerProps = {
37	  variant?: WavyDividerVariant;
38	  /** Stroke weight in px (default 2). Accepts any SVG stroke-width value. */
39	  strokeWeight?: ComponentPropsWithoutRef<"path">["strokeWidth"];
40	  className?: string;
41	} & Omit<ComponentPropsWithoutRef<"svg">, "children" | "className">;
42	
43	// ── Component ─────────────────────────────────────────────────────────────────
44	
45	/**
46	 * Decorative horizontal wave divider. Fills the full width of its container via
47	 * `width="100%"` and an SVG `<pattern>` that tiles automatically — no hooks,
48	 * resize observers, or layout measuring. Stroke color inherits from CSS `color`
49	 * (`currentColor`), so tint it with any text-* utility.
50	 *
51	 * ```tsx
52	 * <WavyDivider variant={WavyDividerVariant.high} className="text-border" />
53	 * ```
54	 */
55	export const WavyDivider = forwardRef<SVGSVGElement, WavyDividerProps>(
56	  (
57	    { variant = WavyDividerVariant.high, strokeWeight = 2, className, ...props },
58	    ref,
59	  ) => {
60	    // Stable, SSR-safe unique id so multiple dividers' <pattern>s never collide.
61	    const patternId = `ds-wave-${useId().replace(/[^a-zA-Z0-9]/g, "")}`;
62	    const tileWidth = TILE_WIDTH[variant];
63	
64	    return (
65	      <svg
66	        ref={ref}
67	        role="presentation"
68	        aria-hidden="true"
69	        width="100%"
70	        height={HEIGHT}
71	        className={cn("block", className)}
72	        {...props}
73	      >
74	        <defs>
75	          <pattern
76	            id={patternId}
77	            x="0"
78	            y="0"
79	            width={tileWidth}
80	            height={HEIGHT}
81	            patternUnits="userSpaceOnUse"
82	          >
83	            <path
84	              d={wavePath(tileWidth)}
85	              fill="none"
86	              stroke="currentColor"
87	              strokeWidth={strokeWeight}
88	              strokeLinecap="round"
89	            />
90	          </pattern>
91	        </defs>
92	        <rect width="100%" height={HEIGHT} fill={`url(#${patternId})`} />
93	      </svg>
94	    );
95	  },
96	);
97	WavyDivider.displayName = "WavyDivider";
