22	
23	/**
24	 * UnderlineLinkText — a "sliding underline" link decoration. The underline is
25	 * present at rest; on hover it wipes out to the right and immediately redraws in
26	 * from the left (a single-hover, two-phase sweep).
27	 *
28	 * The line is a `currentColor` gradient painted into `background`, so it tracks
29	 * this element's own `color` — including hover/active changes on this element or
30	 * an ancestor (e.g. TextLink). Put the color on UnderlineLinkText or above; a
31	 * child that sets its own text color will paint the glyphs but not the underline
32	 * (CSS inheritance only flows downward). No color prop is needed.
33	 *
34	 * Positioned at `1em + offset` from the top of each line box so it sits snug
35	 * under the text like a native `text-decoration` underline, independent of
36	 * leading. Tune with `thickness` / `offset`.
37	 *
38	 * Responds to its own :hover, an ancestor .group:hover, or the `active` prop.
39	 * <TextLink><UnderlineLinkText>Changelog</UnderlineLinkText></TextLink>
40	 */
41	const UnderlineLinkText = forwardRef<HTMLSpanElement, UnderlineLinkTextProps>(
42	  ({ active, thickness, offset, className, style, ...props }, ref) => (
43	    <span
44	      ref={ref}
45	      data-active={active ? "true" : undefined}
46	      className={cn("ds-underline-link", className)}
47	      style={
48	        {
49	          ...(thickness != null
50	            ? { "--ds-underline-thickness": toPxLength(thickness) }
51	            : {}),
52	          ...(offset != null
53	            ? { "--ds-underline-offset": toPxLength(offset) }
54	            : {}),
55	          ...style,
56	        } as CSSProperties
57	      }
58	      {...props}
59	    />
60	  ),
61	);
62	UnderlineLinkText.displayName = "UnderlineLinkText";
63	export { UnderlineLinkText };
