import type { Meta, StoryObj } from "@storybook/react-vite";
import { forwardRef, type AnchorHTMLAttributes } from "react";
import { TextLink } from "./TextLink";
import { BodyText } from "../Text";

const meta = {
  title: "Text/TextLink",
  component: TextLink,
  parameters: { layout: "centered" },
  tags: ["autodocs"],
  argTypes: {
    children: { control: "text" },
    href: { control: "text" },
    asChild: { control: "boolean" },
  },
} satisfies Meta<typeof TextLink>;

export default meta;
type Story = StoryObj<typeof meta>;

export const Default: Story = {
  args: {
    href: "#",
    children: "Read the changelog",
  },
};

/** Stands in for Next.js `Link`: a component that renders its own `<a>` and forwards the ref. */
const RouterLink = forwardRef<
  HTMLAnchorElement,
  AnchorHTMLAttributes<HTMLAnchorElement>
>((props, ref) => <a ref={ref} {...props} />);
RouterLink.displayName = "RouterLink";

export const WithAsChild: Story = {
  name: "asChild with a router link",
  render: () => (
    <TextLink asChild>
      <RouterLink href="#changelog">Changelog</RouterLink>
    </TextLink>
  ),
};

export const InlineSentence: Story = {
  name: "Inline in sentence",
  render: () => (
    <BodyText>
      Learn more about our{" "}
      <TextLink href="#">design principles</TextLink> in the documentation.
    </BodyText>
  ),
};

/* ── Expression details — DS defaults (the signature look) ──────────────────
 * Declared on :root ONLY, not beside `.light`/`.dark`: a theme-class subtree
 * must never quietly restore a detail the practical preset turned off. */
:root {
  /* DropdownCaret shape: 1 = the morphing shape behind the chevron, in its
   * square; 0 = a plain chevron, no shape and no frame around it. Values in
   * between interpolate size and colour; 0 and 1 are the designed settings. */
  --ui-caret-shape-scale: 1; /* expression */
  /* DropdownCaret hover lean (a fraction of one step, like
   * --ui-shape-morph-nudge, which it follows by default); 0 = no lean. */
  --ui-caret-nudge: var(--ui-shape-morph-nudge); /* expression */
}

} /* @layer ds.tokens */

/* ── Expression presets ─────────────────────────────────────────────────────
 * A product-level setting: put the attribute on the root element —
 * `<html data-ds-expression="practical">` in a Next.js app/layout.tsx, or
 * index.html in Vite. Nesting works ("nearest ancestor wins") but is
 * discouraged. Every expression-marked token above MUST appear here with
 * its neutral value. A product's own unlayered tokens.css still beats this. */
@layer ds.expression {
  [data-ds-expression="practical"] {
    --ui-caret-shape-scale: 0;
    --ui-caret-nudge: 0;
  }
}

