@import "tailwindcss" source(none);
/* Scan ONLY the design system's own src/ so the CSS includes every utility the components use. source(none) stops Tailwind's automatic detection from pulling class-like words out of docs, skills and README text into the shipped CSS. Stories are scanned here because Storybook compiles this file; the shipped dist/styles.css is compiled from build.css, which leaves story-only utilities out. */
@source "../**/*.{js,ts,jsx,tsx}";
@import "./tokens.css";
@import "./dooph-component-tokens.css";

/*
 * Toggle Option selection state. Tabs (Radix Tabs) mark the chosen option
 * data-state=active; toggle groups (Radix ToggleGroup) mark it data-state=on.
 * One variant pair lets the shared toggleOptionVariants recipe serve both.
 */
@custom-variant selected (&:is([data-state="active"], [data-state="on"]));
@custom-variant unselected (&:not([data-state="active"], [data-state="on"]));
@plugin "tailwindcss-animate";

/*
 * SidebarWithHoverIcon rail — the two scalars the icon's path is a function of.
 * Registered so they INTERPOLATE: an unregistered custom property is a token
 * string and jumps between values, which is the whole reason these exist.
 *
 *   --ds-sidebar-rail-s  side.  0 = left, 1 = right.
 *   --ds-sidebar-rail-h  hover. 0 = straight rail, 1 = chevron.
 *
 * CSS owns the motion and the component owns only the geometry: it sets the two
 * targets as inline style and samples the interpolated values each frame to
 * write `d` (SVG path data is not itself animatable in every engine). So
 * duration and easing come from the motion scale and reduced motion from its
 * global block, all retunable by a consumer, with no numbers mirrored into
 * JavaScript to drift out of step.
 */
@property --ds-sidebar-rail-s {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}
@property --ds-sidebar-rail-h {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}

/* MorphRotationShape. `step` is the transitioned value the component samples:
 * integer part = stop, fraction = morph progress; the spring ease overshoots,
 * so it runs past each stop. `clock` only exists so autoplay has an animation
 * whose iterations mark each step. */
@property --ds-shape-morph-step {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}
@property --ds-shape-morph-clock {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}
@property --ds-shape-morph-lean {
  syntax: "<number>";
  inherits: false;
  initial-value: 0;
}

/* LoadingSpinner (flat) — Material's circular indeterminate dash, as two
 * numbers animated on the <svg> once per --ui-spinner-duration:
 *   --ds-spinner-grow  0 → 1 → 1   the arc's length, min → max sweep
 *   --ds-spinner-tail  0 → .118 → .985  where the arc's tail sits, in turns
 * Both arc paths compute their dashes from the same two values, so the arc
 * and the track cannot drift apart. Registered so the animation interpolates
 * numbers; inherited so the paths read the values animated on their <svg>. */
@property --ds-spinner-grow {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}
@property --ds-spinner-tail {
  syntax: "<number>";
  inherits: true;
  initial-value: 0;
}

